const G = DojoGame;
function beltArt(index, small = false) {
  const belt = G.BELTS[index];
  return `<span class="belt-drawing ${small ? 'small' : ''}" style="--belt:${belt.color};--stripe:${belt.stripe || belt.color}" role="img" aria-label="Faixa ${belt.name}"><span class="belt-band"></span><span class="belt-tail left-tail"></span><span class="belt-tail right-tail"></span><span class="belt-knot"></span></span>`;
}
function mentor(className = '',days,today) { if(days&&today)return DojoMascot.portrait(days,today,className);return `<img class="sensei-image ${className}" src="assets/sensei-cartoon-limpo.png" alt="Avatar ilustrado do sensei do San Dojo, baseado na sua foto">`; }
function formatDay(key) { return `${key.slice(8, 10)}/${key.slice(5, 7)}`; }
function weekRange() { const start = state.game.currentWeek; return `${formatDay(start)} a ${formatDay(G.shiftDay(start, 6))}`; }
function weekXP() { return G.current(state.game).xp; }
function weeklyMessage() {
  const xp = weekXP(), belt = state.game.belt;
  if (xp >= G.RULES.promoteXP && belt < G.BELTS.length - 1) return 'Meta de subida alcançada! Sua nova faixa chega no fechamento da semana.';
  if (xp >= G.RULES.maintainXP) return belt === 12 ? 'Você já garantiu a permanência na faixa. Continue aprendendo!' : `Faixa protegida! Mais ${Math.max(0, G.RULES.promoteXP - xp)} XP para subir na segunda.`;
  return belt === 0 ? `Faltam ${G.RULES.promoteXP - xp} XP para a primeira subida. Um passo de cada vez!` : `Mais ${G.RULES.maintainXP - xp} XP para manter sua faixa nesta semana.`;
}
function weeklyWidget() { return `<div class="side-card weekly-widget"><div class="side-title"><h3>Minha faixa da semana</h3><span>✦</span></div>${beltArt(state.game.belt)}<h3 class="current-belt-name">${G.BELTS[state.game.belt].name}</h3><span class="week-dates">${weekRange()} · Brasília</span><div class="weekly-score"><b>${weekXP()}</b> / ${G.RULES.promoteXP} XP</div><div class="xp-meter"><span style="width:${Math.min(100, weekXP() / G.RULES.promoteXP * 100)}%"></span><i style="left:40%" title="80 XP: manter a faixa"></i></div><div class="meter-labels"><span>80 · manter</span><span>200 · subir</span></div><p>${weeklyMessage()}</p><button class="outline" data-view="belts">Ver minhas faixas &nbsp; →</button><small class="app-only">Graduação ilustrativa · válida só no app</small></div>`; }
function beltJourney() {
  const game = state.game, xp = weekXP();
  const result = G.outcome(game.belt, xp);
  const nextName = G.BELTS[Math.min(12, game.belt + 1)].name;
  return `<section class="animate-in"><div class="eyebrow">SEU ESFORÇO TEM COR</div><h1>Minha jornada de faixas</h1><p class="intro">Uma faixa por semana. Cada atividade é um passo para evoluir.</p><div class="belt-profile"><div class="mentor-circle">${mentor()}</div><div><span class="eyebrow">SUA FAIXA NO APP</span><h2>${G.BELTS[game.belt].name}</h2><p>O sensei acompanha sua jornada. Vamos juntos!</p><span class="illustrative-label">ILUSTRATIVA · SEM VALIDADE NO DOJO</span></div>${beltArt(game.belt)}</div><div class="weekly-board"><div class="weekly-heading"><div><div class="eyebrow">SEMANA DE ${weekRange()}</div><h2>${xp} <small>/ ${G.RULES.promoteXP} XP</small></h2></div><span class="weekly-status ${xp >= 80 ? 'safe' : ''}">${xp >= 200 && game.belt < 12 ? '✦ Na zona de subida' : xp >= 80 ? '✓ Faixa protegida' : game.belt === 0 ? '🌱 Começando a jornada' : '↗ Hora de praticar'}</span></div><div class="xp-meter"><span style="width:${Math.min(100, xp / 200 * 100)}%"></span><i style="left:40%"></i></div><div class="meter-labels"><span>0 XP</span><span>80 XP · manter</span><span>200 XP · subir</span></div><p>${weeklyMessage()}</p><div class="next-belt">${game.belt < 12 ? `Próxima faixa: <b>${nextName}</b>` : 'Você chegou ao 1º dan ilustrativo. Continue praticando para mantê-lo!'}</div><button class="primary" data-view="practice">Ganhar XP com atividades <span>→</span></button></div><div class="rules-strip"><div><b>✦ 200 XP ou mais</b><p>Sobe 1 faixa ao fechar a semana.</p></div><div><b>✓ 80 a 199 XP</b><p>Mantém a faixa atual.</p></div><div><b>↘ Menos de 80 XP</b><p>Desce 1 faixa. A branca é o início.</p></div></div><p class="week-note">A semana vai de segunda a domingo, no horário de Brasília. O resultado é aplicado na segunda, inclusive ao voltar depois de semanas sem usar o app. No 1º dan, 80 XP já mantêm a faixa. Cada atividade rende 20 XP uma vez por dia.</p><div class="section-head"><h2>As 13 etapas do seu caminho</h2><span class="tiny">${game.belt + 1} / 13</span></div><div class="belt-grid">${G.BELTS.map((b, i) => `<article class="belt-stage ${i === game.belt ? 'is-current' : ''} ${i > game.highestBelt ? 'not-yet' : ''}"><span class="stage-number">${String(i + 1).padStart(2, '0')}</span>${beltArt(i, true)}<h3>${b.name}</h3><small>${i === game.belt ? '● Sua faixa atual' : i <= game.highestBelt ? '✓ Já alcançada' : 'Por conquistar'}</small></article>`).join('')}</div><div class="section-head history-heading"><h2>Seu histórico semanal</h2></div>${game.history.length ? `<div class="history-list">${game.history.slice(-12).reverse().map(item => `<article class="history-row"><div><b>${formatDay(item.week)} a ${formatDay(G.shiftDay(item.week, 6))}</b><small>${item.xp} XP · ${item.kind === 'promoted' ? 'Subiu de faixa' : item.kind === 'demoted' ? 'Desceu uma faixa' : item.kind === 'starting' ? 'Primeiros passos' : 'Manteve a faixa'}</small></div><span>${G.BELTS[item.to].name}</span></article>`).join('')}</div>` : '<div class="info-panel"><p>Seu primeiro resultado aparecerá aqui no fechamento desta semana. Até lá, vamos aprender!</p></div>'}<div class="illustrative-banner">🥋 Estas faixas são recompensas do San Dojo digital. A graduação real de karate é decidida pelo sensei no dojo.</div></section>`;
}
function energyMarkup(){const n=G.refill(state.game),wait=Math.ceil(G.nextChargeMs(state.game)/60000);return `<div class="energy-summary"><div class="energy-large">ϟ <b>${n}</b><small>de 25 energias</small></div><p>${Math.floor(n/5)} atividade(s) disponível(is). Cada atividade usa 5 energias.</p><p>${n<25?'Recarga de +5 em cerca de '+wait+' minuto(s).':'Energia cheia: até 5 atividades.'}</p></div>`;}
function openEnergy(){G.reconcile(state.game);save();stats();const available=window.DojoRewarded?.available();$('#energy-content').innerHTML='<div class="eyebrow">SEU RITMO DE ESTUDO</div><h2>Energia para aprender</h2>'+energyMarkup()+`<div class="energy-explainer"><p>A energia recarrega +5 a cada 30 minutos, até 25. Você pode continuar ouvindo o vocabulário e consultando os materiais enquanto espera.</p><button class="primary" data-reward-ad ${available&&state.game.energy.count<=20?'':'disabled'}>Assistir a um anúncio · +5 energias</button><p class="week-note">${available?'Opcional. A recompensa vale uma atividade e só é concedida quando o anúncio recompensado confirma a conclusão.':'Anúncios recompensados ainda indisponíveis. Use a recarga automática para continuar.'}</p><p id="reward-ad-status" role="status"></p></div>`;$('#energy-dialog').showModal();}
function freeAccessPanel(){return '<div class="info-panel"><div class="eyebrow">VERSÃO GRATUITA</div><h2>Aprender no seu ritmo</h2><p>Você começa com 25 energias, suficientes para cinco atividades. Cada atividade usa 5; a recarga devolve 5 a cada 30 minutos, até o limite de 25.</p><p>Quando disponíveis, anúncios recompensados opcionais podem acrescentar 5 energias. Os materiais e áudios continuam acessíveis durante a recarga.</p></div>';}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-reward-ad]');if(!button)return;button.disabled=true;const status=$('#reward-ad-status');status.textContent='Procurando anúncio disponível…';try{const received=await DojoRewarded.watch(()=>{const amount=G.rewardEnergy(state.game);save();stats();return amount;});if(status.isConnected)status.textContent=received?'Você recebeu +'+received+' energias.':'Não houve recompensa. A recarga automática continua disponível.';if(received)toast('+'+received+' energias recebidas.');}catch{if(status.isConnected)status.textContent='Sem anúncio disponível no momento. A recarga automática continua.';}finally{if(button.isConnected)button.disabled=!DojoRewarded.available()||state.game.energy.count>20;}});
function weeklyRulesPanel() { return `<div class="info-panel"><h2>Como funcionam as faixas do aplicativo</h2><p>Faixa inicial: branca. Com pelo menos 200 XP na semana, o aluno sobe uma etapa na segunda-feira. Com 80 a 199 XP, mantém a etapa. Abaixo de 80 XP, desce uma etapa, sem passar da branca. A sequência segue as 13 categorias informadas pelo San Dojo.</p><p>A pontuação semanal zera a cada segunda-feira, no horário de Brasília. Os XP totais e o histórico continuam salvos. Semanas inteiras sem atividade também contam no retorno. A faixa preta com risco dourado de 1º dan é o limite e requer 80 XP semanais para permanência.</p><p><b>As faixas são ilustrativas e válidas apenas no app.</b> Elas não certificam habilidade técnica nem substituem o exame ou a graduação real do dojo.</p></div>`; }
